<?php
namespace ZCCNG;
if(!defined('ABSPATH'))exit;
final class Candidates{
 private static $instance;
 public static function instance(){if(!self::$instance){self::$instance=new self();self::$instance->hooks();}return self::$instance;}
 private function hooks(){add_action('admin_post_zccng_create_candidate',[$this,'create']);add_action('admin_post_zccng_candidate_status',[$this,'status']);add_action('admin_post_zccng_candidate_profile',[$this,'profile']);add_action('admin_post_zccng_candidate_invitation',[$this,'invitation']);add_action('wp_mail_failed',[$this,'mail_failed']);}
 public static function statuses(){return ['invited','started','submitted','reviewing','interview','offer','hired','declined','suspended','talent_pool','archived'];}
 public static function get($uid){global $wpdb;$t=$wpdb->prefix.'zccng_candidates';return $wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d",$uid),ARRAY_A);}
 public static function all($limit=100){global $wpdb;$t=$wpdb->prefix.'zccng_candidates';$limit=max(1,min(500,(int)$limit));return (array)$wpdb->get_results("SELECT * FROM $t ORDER BY updated_at DESC LIMIT $limit",ARRAY_A);}
 public static function summary(){global $wpdb;$t=$wpdb->prefix.'zccng_candidates';return ['total'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $t"),'submitted'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE status IN ('submitted','reviewing')"),'interviews'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE status='interview'"),'offers'=>(int)$wpdb->get_var("SELECT COUNT(*) FROM $t WHERE status='offer'")];}
 public static function render_candidate_home($uid){$c=self::get($uid);if(!$c)return '<div class="zccng-empty"><b>Temporary candidate profile</b><p>Your candidate record is waiting for HR setup.</p></div>'; $steps=['invited','started','submitted','reviewing','interview','offer','hired'];$current=array_search($c['status'],$steps,true);$o='<div class="zccng-candidate-hero"><span class="zccng-priority zccng-priority--information">'.esc_html(ucwords(str_replace('_',' ',$c['status']))).'</span><h3>'.esc_html($c['position']?:'Position not assigned').'</h3><p>Application reference: '.esc_html($c['application_ref']).'</p></div><div class="zccng-candidate-progress">';foreach($steps as $i=>$step){$state=$current!==false&&$i<=$current?'is-complete':'';$o.='<span class="'.$state.'"><i></i>'.esc_html(ucwords($step)).'</span>';}$o.='</div><form class="zccng-broadcast-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="zccng_candidate_profile">'.wp_nonce_field('zccng_candidate_profile','_wpnonce',true,false).'<div class="zccng-form-row"><label>First name<input name="first_name" value="'.esc_attr($c['first_name']).'"></label><label>Last name<input name="last_name" value="'.esc_attr($c['last_name']).'"></label></div><label>Address<input name="address_line" value="'.esc_attr($c['address_line']).'"></label><div class="zccng-form-row"><label>City<input name="city" value="'.esc_attr($c['city']).'"></label><label>Province / State<input name="region" value="'.esc_attr($c['region']).'"></label></div><div class="zccng-form-row"><label>Country<input name="country" value="'.esc_attr($c['country']).'"></label><label>Postal / ZIP code<input name="postal_code" value="'.esc_attr($c['postal_code']).'"></label></div><label>Phone<input name="phone" value="'.esc_attr($c['phone']).'"></label><label>Resume or portfolio URL<input type="url" name="resume_url" value="'.esc_attr($c['resume_url']).'"></label><button class="zccng-button" type="submit">Save temporary profile</button></form>';return $o;}
 public function create(){if(!Permissions::instance()->can('zccng_manage_candidates'))wp_die('Permission denied',403);check_admin_referer('zccng_create_candidate');$email=sanitize_email($_POST['email']??'');$first=sanitize_text_field($_POST['first_name']??'');$last=sanitize_text_field($_POST['last_name']??'');$position=sanitize_text_field($_POST['position']??'');if(!$email||!is_email($email))wp_die('A valid email is required.',400);$uid=email_exists($email);if(!$uid){$login=sanitize_user(strtok($email,'@'),true);if(username_exists($login))$login.='-'.wp_rand(100,999);$temporary_password=wp_generate_password(20,true);$uid=wp_create_user($login,$temporary_password,$email);if(is_wp_error($uid))wp_die(esc_html($uid->get_error_message()),400);} $user=new \WP_User($uid);$user->set_role('zccng_candidate');wp_update_user(['ID'=>$uid,'first_name'=>$first,'last_name'=>$last,'display_name'=>trim($first.' '.$last)?:$email]);global $wpdb;$t=$wpdb->prefix.'zccng_candidates';$now=current_time('mysql',true);$ref='ZCC-'.gmdate('Y').'-'.str_pad((string)$uid,6,'0',STR_PAD_LEFT);$wpdb->replace($t,['user_id'=>$uid,'application_ref'=>$ref,'status'=>'invited','position'=>$position,'first_name'=>$first,'last_name'=>$last,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now],['%d','%s','%s','%s','%s','%s','%d','%s','%s']);Audit::log('candidate_created','Candidate account created',['candidate_user_id'=>$uid,'position'=>$position]);if(isset($_POST['send_invitation']))$this->send_invitation($uid,['subject'=>sanitize_text_field($_POST['email_subject']??''),'template'=>wp_kses_post($_POST['email_template']??''),'reply_to'=>sanitize_email($_POST['reply_to']??''),'from_email'=>sanitize_email($_POST['from_email']??''),'from_name'=>sanitize_text_field($_POST['from_name']??''),'copy_hr'=>isset($_POST['copy_hr'])]);wp_safe_redirect(admin_url('admin.php?page=zccng-hr&candidate_created=1'));exit;}
 public static function default_subject(){return 'Your {{company_name}} candidate account';}
 public static function default_template(){return "Hello {{candidate_name}},\n\nA temporary candidate account has been created for your application for {{position}}.\n\nApplication reference: {{application_reference}}\nUsername: {{username}}\nSet your password: {{password_setup_url}}\nSign in: {{login_url}}\n\nThis account is for recruitment and employment use only.\n\n{{company_name}}";}
 private function send_invitation($uid,$options=[]){$u=get_userdata($uid);$c=self::get($uid);if(!$u||!$c)return false;$key=get_password_reset_key($u);if(is_wp_error($key))return false;$setup=network_site_url('wp-login.php?action=rp&key='.rawurlencode($key).'&login='.rawurlencode($u->user_login),'login');$tokens=['{{candidate_name}}'=>$u->display_name?:$u->user_login,'{{candidate_email}}'=>$u->user_email,'{{username}}'=>$u->user_login,'{{password_setup_url}}'=>$setup,'{{login_url}}'=>wp_login_url(),'{{position}}'=>$c['position'],'{{application_reference}}'=>$c['application_ref'],'{{company_name}}'=>wp_specialchars_decode(get_bloginfo('name'),ENT_QUOTES),'{{hr_contact}}'=>get_option('admin_email')];$subject=strtr($options['subject']?:self::default_subject(),$tokens);$message=strtr($options['template']?:self::default_template(),$tokens);$headers=['Content-Type: text/plain; charset=UTF-8'];$from_email=sanitize_email($options['from_email']??get_option('admin_email'));$from_name=sanitize_text_field($options['from_name']??get_bloginfo('name'));if($from_email&&is_email($from_email))$headers[]='From: '.$from_name.' <'.$from_email.'>';if(!empty($options['reply_to'])&&is_email($options['reply_to']))$headers[]='Reply-To: '.$options['reply_to'];if(!empty($options['copy_hr'])&&is_email(get_option('admin_email')))$headers[]='Cc: '.get_option('admin_email');$sent=wp_mail($u->user_email,$subject,wp_strip_all_tags($message),$headers);global $wpdb;$wpdb->update($wpdb->prefix.'zccng_candidates',['invitation_status'=>$sent?'processed':'failed','invitation_sent_at'=>current_time('mysql',true),'invitation_error'=>$sent?'':__('WordPress mail transport returned false. Check SMTP or the hosting mail service.','zincontrolcenter-nextgen'),'updated_at'=>current_time('mysql',true)],['user_id'=>$uid]);Audit::log($sent?'candidate_invitation_sent':'candidate_invitation_failed',$sent?'Candidate invitation sent':'Candidate invitation failed',['candidate_user_id'=>$uid]);return $sent;}
 public function mail_failed($error){$data=$error instanceof \WP_Error?$error->get_error_data():[];$to=(array)($data['to']??[]);$message=$error instanceof \WP_Error?$error->get_error_message():'Unknown WordPress mail error';global $wpdb;$t=$wpdb->prefix.'zccng_candidates';foreach($to as $email){$uid=email_exists($email);if($uid)$wpdb->update($t,['invitation_status'=>'failed','invitation_error'=>sanitize_text_field($message),'updated_at'=>current_time('mysql',true)],['user_id'=>$uid]);}Audit::log('wp_mail_failed','WordPress mail transport failed',['message'=>$message,'recipients'=>$to]);}
 public function invitation(){if(!Permissions::instance()->can('zccng_manage_candidates'))wp_die('Permission denied',403);$uid=absint($_POST['user_id']??0);check_admin_referer('zccng_candidate_invitation_'.$uid);if(!$uid||!self::get($uid))wp_die('Candidate not found',404);$this->send_invitation($uid,['subject'=>sanitize_text_field($_POST['email_subject']??''),'template'=>wp_kses_post($_POST['email_template']??''),'reply_to'=>sanitize_email($_POST['reply_to']??''),'from_email'=>sanitize_email($_POST['from_email']??''),'from_name'=>sanitize_text_field($_POST['from_name']??''),'copy_hr'=>isset($_POST['copy_hr'])]);wp_safe_redirect(admin_url('admin.php?page=zccng-hr&invitation_sent=1'));exit;}
 public function status(){if(!Permissions::instance()->can('zccng_manage_candidates'))wp_die('Permission denied',403);$uid=absint($_GET['user_id']??0);$status=sanitize_key($_GET['status']??'');check_admin_referer('zccng_candidate_status_'.$uid);if(!$uid||!in_array($status,self::statuses(),true))wp_die('Invalid request',400);global $wpdb;$t=$wpdb->prefix.'zccng_candidates';$wpdb->update($t,['status'=>$status,'updated_at'=>current_time('mysql',true)],['user_id'=>$uid],['%s','%s'],['%d']);$u=new \WP_User($uid);if($status==='hired')$u->set_role('zccng_staff');if(in_array($status,['suspended','archived'],true))update_user_meta($uid,'zccng_account_restricted',1);else delete_user_meta($uid,'zccng_account_restricted');Audit::log('candidate_status_changed','Candidate status changed',['candidate_user_id'=>$uid,'status'=>$status]);wp_safe_redirect(admin_url('admin.php?page=zccng-hr'));exit;}
 public function profile(){if(!current_user_can('read'))wp_die('Permission denied',403);check_admin_referer('zccng_candidate_profile');$uid=get_current_user_id();$c=self::get($uid);if(!$c)wp_die('Candidate profile not found.',404);$allowed=['first_name','last_name','address_line','city','region','country','postal_code','phone','resume_url'];$data=[];foreach($allowed as $key)$data[$key]=$key==='resume_url'?esc_url_raw($_POST[$key]??''):sanitize_text_field($_POST[$key]??'');$data['status']=$c['status']==='invited'?'started':$c['status'];$data['updated_at']=current_time('mysql',true);global $wpdb;$wpdb->update($wpdb->prefix.'zccng_candidates',$data,['user_id'=>$uid]);wp_update_user(['ID'=>$uid,'first_name'=>$data['first_name'],'last_name'=>$data['last_name'],'display_name'=>trim($data['first_name'].' '.$data['last_name'])]);Audit::log('candidate_profile_updated','Candidate profile updated');wp_safe_redirect(admin_url('admin.php?page=zccng-staff-hub&profile_saved=1'));exit;}
}
